import{mountShell}from'../shared/shell.js?v=0.3.0';import{attachCardDrag}from'../shared/drag.js';import{readStore,writeStore,downloadText}from'../shared/utils.js';import{lineChart}from'../model-kit/chart.js';import{create,validate,simulate,threshold,COUNT}from'./engine.js';mountShell({active:'predictions'});const app=document.querySelector('#app'),KEY='thinking-lab:predictions:v1';let saved=readStore(KEY,null),s,baseline,week=Number.isFinite(saved?.week)?saved.week:0,past=[],destroy=()=>{},message='';try{s=validate(saved?.s||create());baseline=saved?.baseline?validate(saved.baseline):null;}catch{s=create();baseline=null;}week=Math.min(39,Math.max(0,Math.round(week)));const f=x=>x.toFixed(1);function save(){writeStore(KEY,{s,baseline,week});}function change(fn,msg='Same underlying prices replayed.'){past.push({s:structuredClone(s),baseline:structuredClone(baseline)});past=past.slice(-35);fn();validate(s);message=msg;save();render();}function render(){destroy();const r=simulate(s),b=baseline?simulate({...baseline,scenario:s.scenario}):null,row=r.history[week];app.innerHTML=`<section class="surface"><div class="toolbar"><label for="scenario">Underlying price pattern</label><select id="scenario">${[['steady','Nearly steady'],['wave','A changing daily pattern'],['shift','A step in underlying demand']].map(([k,l])=>`<option value="${k}" ${s.scenario===k?'selected':''}>${l}</option>`).join('')}</select><button id="pin">Pin baseline</button><button id="undo" ${!past.length?'disabled':''}>Undo</button><button id="reset">Reset</button></div><p class="status" role="status">${message||'Move participants between shared and private signals. Private estimates update more slowly and differ across participants.'}</p><div class="signal-board">${['common','private'].map(group=>`<section class="signal-group ${group}" data-drop-id="${group}"><h2>${group==='common'?'One shared forecast':'Separate slow estimates'}</h2><p class="hint">${s.common.filter(v=>v===(group==='common')).length} participants · drag a handle or activate it to switch.</p><div class="agents">${s.common.map((v,i)=>v===(group==='common')?`<article data-drag-id="${i}" class="agent"><button data-drag-handle data-agent="${i}" aria-label="Participant ${i+1}, ${group} signal. Activate to switch."><span>${String(i+1).padStart(2,'0')}</span><strong>${row.actions[i]>=0?'↑':'↓'} ${Math.round(Math.abs(row.actions[i])*100)}%</strong></button><small>Threshold ${f(threshold(s,i))}</small></article>`:'').join('')}</div></section>`).join('')}</div><div class="toolbar"><button data-all="common">All share</button><button data-all="mixed">Half share</button><button data-all="private">All separate</button></div></section><div class="split"><section class="surface"><h2>Watch the feedback</h2><div class="key"><span><b></b>Realised price</span><span><b></b>Shared forecast</span><span>Grey: underlying / pinned</span></div><div class="chart" role="img" aria-label="Realized price, shared forecast and underlying price over 40 rounds">${lineChart([{values:r.history.map(x=>x.price)},{values:r.history.map(x=>x.shared),color:'#b98545'},{values:r.history.map(x=>x.base),color:'#9dafc4',dashed:true},...(b?[{values:b.history.map(x=>x.price),color:'#829788',dashed:true}]:[])],{min:-20,max:120,cursor:week,labels:['Round 1','Round 40']})}</div><div class="field"><label for="week">Inspect round <output>${week+1}</output></label><input id="week" type="range" min="0" max="39" value="${week}"></div><p class="round-info">Forecast ${f(row.shared)} → mean response ${f(row.mean*100)}% → realised ${f(row.price)}. Underlying price without response: ${f(row.base)}.</p></section><section class="surface"><h2>Change how the feedback works</h2><div class="fields">${[['reaction','Forecast update speed',.05,1,.05],['sensitivity','Response to price difference',.1,3,.1],['diversity','Spread of willingness thresholds',0,30,1],['impact','Price impact at full response',0,50,1],['initial','First shared forecast',0,100,1]].map(([k,l,min,max,step])=>`<div class="field"><label for="${k}">${l} <output>${f(s[k])}</output></label><input data-param="${k}" id="${k}" type="range" min="${min}" max="${max}" step="${step}" value="${s[k]}"></div>`).join('')}</div><p class="hint">Sharing, diversity, speed and price impact interact. A faster response can correct a stale estimate or overshoot it.</p></section></div><section class="metrics"><div class="metric"><span>Mean change between rounds</span><strong>${f(r.oscillation)}</strong><small>${b?`${f(b.oscillation)} in baseline`:'Price units; not a risk estimate'}</small></div><div class="metric"><span>Shared forecast mean absolute error</span><strong>${f(r.error)}</strong><small>After the response changed price</small></div><div class="metric"><span>Realised price range</span><strong>${f(r.range)}</strong><small>Maximum minus minimum</small></div><div class="metric"><span>Common signal users</span><strong>${s.common.filter(Boolean).length}/${COUNT}</strong><small>All see the same published estimate</small></div></section><details><summary>Mechanism, timing and limits</summary><p>Each participant has a willingness threshold centred on 50. Its action = clamp(sensitivity × (threshold − signal) / 20, −1,+1). Positive means charging; negative means discharge. Realised price = underlying price + price impact × mean action. The shared forecast then moves toward that realised price for the next round. It never sees the next underlying price.</p><p>Private estimates use an 8% update rate plus small deterministic differing offsets. Diversity spreads thresholds; it is separate from private information. These are repeated hypothetical clearing rounds with unit-size participants, no state of charge, inventory, network limits, bids or learning. The chart is a mechanism sketch, not a battery-market forecast. Pinned runs share the same underlying pattern.</p></details><p class="local-note">Plan and baseline save in this browser. ↑ charge adds demand; ↓ discharge adds supply.</p>`;bind();destroy=attachCardDrag({root:app,onDrop:({itemId,dropId})=>change(()=>s.common[+itemId]=dropId==='common','Signal assignment changed. The whole sequence replays.')});}
function bind(){app.querySelectorAll('[data-agent]').forEach(el=>el.onclick=()=>change(()=>s.common[+el.dataset.agent]=!s.common[+el.dataset.agent]));app.querySelectorAll('[data-all]').forEach(el=>el.onclick=()=>change(()=>s.common=s.common.map((_,i)=>el.dataset.all==='common'||el.dataset.all==='mixed'&&i<12)));app.querySelectorAll('[data-param]').forEach(el=>el.onchange=()=>{const k=el.dataset.param,v=+el.value;change(()=>s[k]=v);});document.querySelector('#scenario').onchange=ev=>{const v=ev.target.value;change(()=>s.scenario=v);};document.querySelector('#week').onchange=ev=>{week=+ev.target.value;save();render();};document.querySelector('#pin').onclick=()=>change(()=>baseline=structuredClone(s),'Baseline pinned. Compare on the same underlying pattern.');document.querySelector('#undo').onclick=()=>{const p=past.pop();if(p){s=p.s;baseline=p.baseline;save();render();}};document.querySelector('#reset').onclick=()=>change(()=>s=create(),'Default feedback restored.');}document.querySelector('#export').onclick=()=>downloadText('prediction-feedback.md',`# When predictions change behaviour\n\nFictional repeated clearing model. Same underlying pattern in both plans. No state of charge or financial calibration.\n\n\`\`\`json\n${JSON.stringify({settings:s,baseline,result:simulate(s),baselineResult:baseline?simulate({...baseline,scenario:s.scenario}):null},null,2)}\n\`\`\`\n`,'text/markdown');render();
